public async Task<Result<Invoice>> GetAsync(int id, CancellationToken cancellationToken)
{
    var invoice = await store.FindAsync(id, cancellationToken);

    return invoice is null
        ? Error.NotFound("invoice.missing", $"No invoice with id {id}.")
        : invoice;
}

// Compose without unpacking; every step short-circuits on failure, awaited or not.
return await GetAsync(id, cancellationToken)
    .Ensure(i => i.IsOpen, Error.Conflict("invoice.closed", "Already closed."))
    .Map(i => i.ToModel());

// A command produces no value, and the valueless Result composes the same way.
return Authorize(user, invoice)
    .Bind(() => Close(invoice))
    .TapError(errors => logger.LogWarning("Could not close {Invoice}: {Errors}", invoice.Id, errors));

// Carrying a failure into another type, without restating its reasons.
if (invoice.IsFailure) return invoice.Cast<InvoiceModel>();
